using System;
using UnityEngine;

namespace FPS
{
    /// <summary>
    /// Imported (Asset Store) gun meshes for the procedural weapons. Resources/WeaponModels.asset,
    /// generated by Tools > FPS > Build Character Models (it builds both databases).
    /// </summary>
    public class WeaponModelDB : ScriptableObject
    {
        [Serializable]
        public class Entry
        {
            public string weaponName;
            public GameObject prefab;
            /// <summary>Keep the procedural magazine visible (shotgun: it is the shell in the hand).</summary>
            public bool keepMagazine;
            /// <summary>Extra scale on top of the length fit.</summary>
            public float scale = 1f;
            /// <summary>Extra offset (model space, meters) after the fit.</summary>
            public Vector3 offset;
            /// <summary>The imported gun has its own sights/optic: procedural optics are hidden and ADS lines up on sightPoint.</summary>
            public bool ownSight;
            /// <summary>Sight line point in the imported prefab's root space (reticle center / top of front post).</summary>
            public Vector3 sightPoint;
            /// <summary>&gt;0: the mesh keeps this absolute scale and is aligned on its trigger (instead of being stretched
            /// over the procedural gun); the muzzle and the support hand move to the imported gun.</summary>
            public float fixedScale;
            /// <summary>Only the sight height comes from sightPoint; the eye distance stays the procedural one.</summary>
            public bool sightKeepDepth;
            /// <summary>Measured by the builder (FBX root space): trigger center, muzzle center, foregrip center.</summary>
            public Vector3 triggerPoint, muzzlePoint, foregripPoint;
            public bool hasForegrip;
        }

        public Entry[] entries = new Entry[0];

        [Header("Melee")]
        public GameObject knifePrefab;
        public Vector3 knifeEuler, knifeOffset = new Vector3(0f, 0.004f, 0.02f);
        public float knifeScale = 1f;

        static WeaponModelDB instance;
        static bool loaded;
        public static WeaponModelDB Instance
        {
            get
            {
                if (!loaded) { instance = Resources.Load<WeaponModelDB>("WeaponModels"); loaded = true; }
                return instance;
            }
        }

        public static Entry Get(string weaponName)
        {
            var db = Instance;
            if (!db || string.IsNullOrEmpty(weaponName)) return null;
            foreach (var e in db.entries) if (e != null && e.prefab && e.weaponName == weaponName) return e;
            return null;
        }
    }
}
